package android.content; import java.io.File; public class Context {public static final String ACTIVITY_SERVICE="activity",CLIPBOARD_SERVICE="clipboard"; public Context getApplicationContext(){return this;} public File getCacheDir(){return getFilesDir();} public File getFilesDir(){return new File(System.getProperty("diag.dir"));} public String getPackageName(){return "app.paradox.youtubeintegrated";} public Object getSystemService(String s){return s.equals(CLIPBOARD_SERVICE)?new ClipboardManager():new android.app.ActivityManager();}}